'use strict';
// A fake Vizio TV: HTTPS with a throwaway self-signed cert generated by openssl.
const https = require('https');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

const ok = (extra) => ({ STATUS: { RESULT: 'SUCCESS', DETAIL: 'Success' }, ...extra });

function makeCert() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'vizio-stub-'));
  execFileSync('openssl', ['req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-keyout', path.join(dir, 'k.pem'), '-out', path.join(dir, 'c.pem'), '-days', '2', '-subj', '/CN=stub'], { stdio: 'ignore' });
  const out = { key: fs.readFileSync(path.join(dir, 'k.pem')), cert: fs.readFileSync(path.join(dir, 'c.pem')) };
  fs.rmSync(dir, { recursive: true, force: true });
  return out;
}

async function startStub({ token = 'TESTTOKEN', pin = '1234' } = {}) {
  const state = { power: 1, volume: 30, mute: 'Off', input: 'HDMI-3', requests: [], keys: [] };
  const server = https.createServer(makeCert(), (req, res) => {
    let raw = '';
    req.on('data', (c) => (raw += c));
    req.on('end', () => {
      const body = raw ? JSON.parse(raw) : undefined;
      state.requests.push({ method: req.method, url: req.url, body, auth: req.headers.auth });
      const send = (obj, code = 200) => { res.writeHead(code, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(obj)); };
      if (req.url === '/pairing/start') return send(ok({ ITEM: { CHALLENGE_TYPE: 1, PAIRING_REQ_TOKEN: 42 } }));
      if (req.url === '/pairing/pair') {
        if (body.RESPONSE_VALUE !== pin) return send({ STATUS: { RESULT: 'CHALLENGE_INCORRECT', DETAIL: 'Wrong PIN' } });
        return send(ok({ ITEM: { AUTH_TOKEN: token } }));
      }
      if (req.url === '/pairing/cancel') return send(ok({}));
      if (req.headers.auth !== token) return send({ STATUS: { RESULT: 'BLOCKED', DETAIL: 'Not authorized' } }, 403);
      if (req.url === '/key_command/') { body.KEYLIST.forEach((k) => state.keys.push([k.CODESET, k.CODE])); return send(ok({})); }
      if (req.url === '/state/device/power_mode') return send(ok({ ITEMS: [{ VALUE: state.power }] }));
      if (req.url === '/menu_native/dynamic/tv_settings/audio/volume') {
        if (req.method === 'PUT') { state.volume = body.VALUE; return send(ok({})); }
        return send(ok({ ITEMS: [{ VALUE: state.volume, HASHVAL: 111 }] }));
      }
      if (req.url === '/menu_native/dynamic/tv_settings/audio/mute') return send(ok({ ITEMS: [{ VALUE: state.mute }] }));
      if (req.url === '/menu_native/dynamic/tv_settings/devices/current_input') {
        if (req.method === 'PUT') { state.input = body.VALUE; state.inputHash = body.HASHVAL; return send(ok({})); }
        return send(ok({ ITEMS: [{ VALUE: state.input, HASHVAL: 222 }] }));
      }
      if (req.url === '/menu_native/dynamic/tv_settings/devices/name_input') {
        return send(ok({ ITEMS: [
          { CNAME: 'cast', NAME: 'CAST', VALUE: { NAME: 'SMARTCAST' } },
          { CNAME: 'hdmi1', NAME: 'HDMI-1', VALUE: { NAME: 'HDMI-1' } },
          { CNAME: 'hdmi2', NAME: 'HDMI-2', VALUE: { NAME: 'Game Console' } }
        ] }));
      }
      send({ STATUS: { RESULT: 'URI_NOT_FOUND' } }, 404);
    });
  });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  return { state, port: server.address().port, token, pin, close: () => new Promise((r) => { server.closeAllConnections && server.closeAllConnections(); server.close(r); }) };
}

module.exports = { startStub };
